/* Team location: read-only workspace over the existing scoped field API. */
let locDataScope='',locDetail='',locQuery='',locBucket='',locJourney=false,locPopup=false,locClusterIds=[];
const locIcon=(kind)=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+({clock:'<circle cx="12" cy="13" r="8"/><path d="M12 9v4l3 2M5 2 2 5m17-3 3 3"/>',timer:'<circle cx="12" cy="14" r="8"/><path d="M12 10v4m-3-12h6m-3 0v4"/>',history:'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7m2-4v6l4 2"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="3"/>',device:'<rect x="6" y="2" width="12" height="20" rx="2"/><path d="M10 18h4"/>',battery:'<rect x="3" y="6" width="16" height="12" rx="2"/><path d="M22 10v4M6 9v6"/>',signal:'<path d="M4 20v-4m5 4v-8m5 8V8m5 12V4"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',back:'<path d="m12 5-7 7 7 7m-7-7h16"/>'})[kind]+'</svg>';
function locAge(p,time=Date.now()){if(!p||p.lat==null||p.lng==null||p.lat===''||p.lng===''||!Number.isFinite(Number(p.lat))||!Number.isFinite(Number(p.lng))||Math.abs(Number(p.lat))>90||Math.abs(Number(p.lng))>180)return null;const ms=Date.parse(p.captured);return Number.isFinite(ms)&&ms<=time+300000?Math.max(0,(time-ms)/60000):null}
function locStatus(p,time=Date.now()){const min=locAge(p,time);return min===null?'none':min<=10?'fresh':min<=60?'recent':'stale'}
function locAgo(p){const min=locAge(p);if(min===null)return 'Belum ada lokasi';if(min<1)return 'Baru saja';if(min<60)return Math.floor(min)+' menit lalu';if(min<1440)return Math.floor(min/60)+' jam lalu';return Math.floor(min/1440)+' hari lalu'}
function locAction(p){return ({'clock-in':'Absen Masuk','clock-out':'Absen Pulang',journey:'Pembaruan Lokasi'})[p?.kind]||'Belum ada aktivitas lokasi'}
function locInitials(name){return String(name||'?').trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
function locScope(){return (authUser?.id||'')+'|'+activeBranch}
function locMembers(){return (locDataScope===locScope()?fieldData?.members||[]:[]).filter(m=>m.active!==false)}
function locRows(){const q=locQuery.trim().toLocaleLowerCase('id');return locMembers().filter(m=>(!locBucket||locStatus(m.latest)===locBucket)&&(!q||[m.name,m.role,m.userId||m.id].join(' ').toLocaleLowerCase('id').includes(q))).sort((a,b)=>(Date.parse(b.latest?.captured)||0)-(Date.parse(a.latest?.captured)||0)||a.name.localeCompare(b.name,'id'))}
function locHandler(fn,id){return E(fn+'('+JSON.stringify(id)+')')}
function locOpen(id){if(!locMembers().some(m=>m.id===id))return;locDetail=id;locPopup=false;locClusterIds=[];locJourney=false;fieldSelectMember(id);renderContent()}
function locBack(){stopJourneyReplay();locDetail='';locPopup=false;locClusterIds=[];locJourney=false;mapState.fitted=false;renderContent()}
function locFilter(bucket){locBucket=locBucket===bucket?'':bucket;locBack()}
function locSearch(value){locQuery=value;const list=document.querySelector('#locMemberList'),count=document.querySelector('#locResultCount');if(list)list.innerHTML=locList();if(count)count.textContent=locRows().length+' dari '+locMembers().length+' anggota';mapState.fitted=false;drawFieldMap()}
function locList(){const rows=locRows();return rows.map(m=>'<button type="button" class="loc-member" onclick="'+locHandler('locOpen',m.id)+'"><span class="loc-recency '+locStatus(m.latest)+'">'+E(locAgo(m.latest))+'</span><span class="loc-member-body"><span class="loc-avatar">'+E(locInitials(m.name))+'</span><span class="loc-member-copy"><strong>'+E(m.name)+'</strong><small>'+E(m.role)+'</small><span>'+E(locAction(m.latest))+'</span><small>'+E(m.latest?Number(m.latest.lat).toFixed(5)+', '+Number(m.latest.lng).toFixed(5):'Lokasi belum dibagikan')+'</small></span><i class="loc-dot '+locStatus(m.latest)+'" aria-label="'+E(locAgo(m.latest))+'"></i></span></button>').join('')||'<div class="loc-empty">'+E(fieldLoading?'Memuat anggota…':'Tidak ada anggota sesuai pencarian dan filter.')+'</div>'}
function locFact(icon,title,value){return '<div class="loc-fact">'+locIcon(icon)+'<div><dt>'+E(title)+'</dt><dd>'+E(value)+'</dd></div></div>'}
function locCoordinates(p){return locAge(p)===null?'Belum tersedia':Number(p.lat).toFixed(6)+', '+Number(p.lng).toFixed(6)}
function locSide(){const m=locMembers().find(m=>m.id===locDetail);if(!m)return '<div class="loc-side-head"><h2>Anggota tim</h2><small id="locResultCount">'+locRows().length+' dari '+locMembers().length+' anggota</small></div><label class="loc-search">'+locIcon('search')+'<input type="search" aria-label="Cari anggota lokasi" placeholder="Cari nama atau User ID" value="'+E(locQuery)+'" oninput="locSearch(this.value)"></label><div id="locMemberList" class="loc-member-list">'+locList()+'</div>';
const p=m.latest;return '<button type="button" class="loc-back" onclick="locBack()">'+locIcon('back')+'Semua anggota</button><div class="loc-person"><span class="loc-avatar">'+E(locInitials(m.name))+'</span><div><h2>'+E(m.name)+'</h2><small>'+E(m.role)+' · '+E(m.userId||m.id)+'</small></div></div><span class="loc-recency '+locStatus(p)+'">'+E(locAgo(p))+'</span><dl class="loc-facts">'+locFact('pin','Posisi terakhir diterima',p?.address||locCoordinates(p))+locFact('clock','Aktivitas lokasi terakhir',locAction(p))+locFact('history','Pembaruan terakhir',p?fieldTime(p.captured)+' WITA':'Belum tersedia')+locFact('pin','Akurasi GPS',locAge(p)!==null?'±'+Math.round(Number(p.accuracy)||0)+' meter':'Belum tersedia')+locFact('device','Perangkat',p?.device||'Belum tersedia')+'<div class="loc-device-grid">'+locFact('battery','Baterai',typeof p?.battery==='number'?p.battery+'%':'Belum tersedia')+locFact('signal','Sinyal',p?.signal??'Belum tersedia')+'</div></dl><p class="loc-note">Lokasi terakhir diterima, bukan jaminan posisi saat ini. Informasi perangkat belum dikirim oleh aplikasi web.</p>'}
function locToggleJourney(value){stopJourneyReplay();locJourney=value;locPopup=false;mapState.fitted=false;renderContent()}
locationScreen=function(){
if(locDetail&&!locMembers().some(m=>m.id===locDetail)){locDetail='';locJourney=false}const members=locMembers(),counts={fresh:0,recent:0,stale:0,none:0};members.forEach(m=>counts[locStatus(m.latest)]++);const selected=members.find(m=>m.id===locDetail),points=locJourney&&fieldData?.selected===locDetail?fieldData.points||[]:[],distance=points.slice(1).reduce((sum,p,i)=>sum+fieldDistance(points[i],p),0);
const stats=[['fresh','clock','Diperbarui ≤10 menit'],['recent','timer','Diperbarui >10–60 menit'],['stale','history','Diperbarui >60 menit']].map(([key,icon,label])=>'<button type="button" class="loc-stat '+(locBucket===key?'selected':'')+'" aria-pressed="'+(locBucket===key)+'" onclick="locFilter(\''+key+'\')"><span class="loc-stat-icon">'+locIcon(icon)+'</span><strong>'+counts[key]+'</strong><span>'+label+'</span></button>').join('');
return '<section class="loc-workspace"><div class="loc-page-head"><div><h1>'+E(authUser.role==='AO'?'Lokasi Saya':'Lokasi Tim')+'</h1><p>'+E(activeBranch)+' · WITA</p></div><button type="button" onclick="loadField(true)" '+(fieldLoading?'disabled':'')+'>'+E(fieldLoading?'Memperbarui…':'Perbarui')+'</button></div>'+(fieldError?'<p class="error" role="alert">'+E(fieldError)+'</p>':'')+'<div class="loc-layout"><div class="loc-sidebar">'+locSide()+'</div><div class="loc-main"><div class="loc-stats">'+stats+'</div><div class="loc-map-toolbar"><small>'+members.length+' anggota · '+counts.none+' belum memiliki lokasi'+(locBucket?' · Filter waktu aktif':'')+'</small><div>'+(selected?'<button type="button" aria-pressed="'+!locJourney+'" onclick="locToggleJourney(false)">Lokasi terakhir</button><button type="button" aria-pressed="'+locJourney+'" onclick="locToggleJourney(true)">Journey</button>':'<button type="button" onclick="locBucket=\'\';locQuery=\'\';locBack()">Tampilkan semua</button>')+'</div></div>'+(selected&&locJourney?'<div class="loc-journey-controls"><label>Tanggal journey<input type="date" aria-label="Tanggal journey" value="'+E(fieldDay)+'" onchange="fieldSelectDay(this.value)"></label><button type="button" onclick="toggleJourneyReplay()">'+(replayTimer?'Jeda Journey':'Putar Journey')+'</button><small>'+points.length+' titik · '+(distance/1000).toLocaleString('id-ID',{maximumFractionDigits:2})+' km</small><span id="replayTime"></span></div>':'')+'<div id="fieldMap" class="fieldmap loc-map" role="region" aria-label="Peta lokasi anggota"><div id="fieldMapLayers"></div><div class="mapcontrols"><button type="button" onclick="changeMapZoom(1)" aria-label="Perbesar peta">+</button><button type="button" onclick="changeMapZoom(-1)" aria-label="Perkecil peta">−</button><button type="button" onclick="mapState.fitted=false;drawFieldMap()" aria-label="Sesuaikan tampilan peta">⌖</button></div>'+(selected?'<div class="loc-map-banner"><strong>'+E(locJourney?'Journey · '+fieldDay:locAction(selected.latest))+'</strong><span>'+E(selected.latest?.address||locCoordinates(selected.latest))+'</span></div>':'')+'<div id="locTileError" class="loc-tile-error" hidden>Tile peta gagal dimuat. Daftar dan koordinat tetap tersedia.</div><a class="mapcredit" href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">© OpenStreetMap contributors</a></div><p class="loc-note">Waktu aktif dihitung dari pembaruan GPS terakhir. '+(locJourney?'Garis menghubungkan sampel GPS, bukan rute jalan.':'Klik anggota atau pin untuk melihat detail. Lokasi tetap mengikuti hak akses kantor.')+'</p>'+(locJourney?'<details class="loc-timeline"><summary>Timeline Journey · '+points.length+' titik</summary>'+points.slice(-fieldTimelineLimit).map(p=>'<button type="button" class="gpsrow" onclick="'+locHandler('focusGPSPoint',p.id)+'"><span>'+E(fieldTime(p.captured))+'</span><strong>'+E(locAction(p))+'</strong><small>'+E(locCoordinates(p))+'</small></button>').join('')+(points.length?'':'<p class="loc-empty">Belum ada titik GPS pada tanggal ini.</p>')+(points.length>fieldTimelineLimit?'<button onclick="fieldTimelineLimit+=100;renderContent()">Tampilkan titik sebelumnya</button>':'')+'</details>':'')+'</div></div></section>';
};
function locMapMembers(){return locDetail?locMembers().filter(m=>m.id===locDetail&&locAge(m.latest)!==null):locRows().filter(m=>locAge(m.latest)!==null)}
function locClusters(members,pos){const groups=new Map();for(const m of members){const q=pos(m.latest),key=Math.floor(q.x/56)+':'+Math.floor(q.y/56),g=groups.get(key)||[];g.push(m);groups.set(key,g)}return [...groups.values()]}
fitFieldMap=function(w,h){const selected=locMembers().find(m=>m.id===locDetail),points=locJourney&&fieldData?.selected===locDetail?fieldData.points||[]:[],a=points.length?points:locDetail&&locAge(selected?.latest)!==null?[selected.latest]:locMapMembers().map(m=>m.latest);if(!a.length){Object.assign(mapState,{lat:-8.65,lng:115.2167,zoom:12,fitted:true});return}if(a.length===1){const point=projectMap(Number(a[0].lat),Number(a[0].lng),16);Object.assign(mapState,{...unprojectMap(point.x,point.y-(locDetail?70:0),16),zoom:16,fitted:true});return}for(let z=17;z>=3;z--){const ps=a.map(p=>projectMap(Number(p.lat),Number(p.lng),z)),xs=ps.map(p=>p.x),ys=ps.map(p=>p.y),minx=Math.min(...xs),maxx=Math.max(...xs),miny=Math.min(...ys),maxy=Math.max(...ys);if(maxx-minx<Math.max(90,w-130)&&maxy-miny<Math.max(90,h-190)||z===3){Object.assign(mapState,{...unprojectMap((minx+maxx)/2,(miny+maxy)/2,z),zoom:a.length===1?16:z,fitted:true});return}}};
function locMarker(id){if(locDetail===id){locPopup=!locPopup;locClusterIds=[];drawFieldMap()}else{locOpen(id);locPopup=true}}
function locCluster(index){const members=locMapMembers(),w=document.querySelector('#fieldMap').clientWidth,h=document.querySelector('#fieldMap').clientHeight,c=projectMap(mapState.lat,mapState.lng,mapState.zoom),pos=p=>{const q=projectMap(p.lat,p.lng,mapState.zoom);return{x:q.x-c.x+w/2,y:q.y-c.y+h/2}},group=locClusters(members,pos)[index];if(!group)return;if(mapState.zoom>=17){locClusterIds=group.map(m=>m.id);drawFieldMap();return}mapState.lat=group.reduce((n,m)=>n+Number(m.latest.lat),0)/group.length;mapState.lng=group.reduce((n,m)=>n+Number(m.latest.lng),0)/group.length;mapState.zoom=Math.min(18,mapState.zoom+2);mapState.fitted=true;drawFieldMap()}
const locationDrawBase=drawFieldMap;
drawFieldMap=function(){if(view!=='Lokasi Tim')return locationDrawBase();const map=document.querySelector('#fieldMap'),layers=document.querySelector('#fieldMapLayers');if(!map||!layers)return;const w=map.clientWidth||330,h=map.clientHeight||430;if(!mapState.fitted)fitFieldMap(w,h);const z=mapState.zoom,c=projectMap(mapState.lat,mapState.lng,z),left=c.x-w/2,top=c.y-h/2,n=2**z,pos=p=>{const q=projectMap(Number(p.lat),Number(p.lng),z);return{x:q.x-left,y:q.y-top}};let tiles='';for(let x=Math.floor(left/256);x<=Math.floor((left+w)/256);x++)for(let y=Math.floor(top/256);y<=Math.floor((top+h)/256);y++)if(y>=0&&y<n)tiles+='<img class="maptile" alt="" draggable="false" onerror="document.querySelector(\'#locTileError\').hidden=false" src="https://tile.openstreetmap.org/'+z+'/'+((x%n+n)%n)+'/'+y+'.png" style="left:'+(x*256-left)+'px;top:'+(y*256-top)+'px">';
const points=locJourney&&fieldData?.selected===locDetail?fieldData.points||[]:[],poly=points.map(p=>{const q=pos(p);return q.x+','+q.y}).join(' ');let route=points.length?'<svg class="routelayer" viewBox="0 0 '+w+' '+h+'" aria-hidden="true"><polyline points="'+poly+'" fill="none" stroke="#087EE1" stroke-width="4" stroke-linejoin="round"/></svg>':'';
const groups=locClusters(locMapMembers(),pos);let markers=groups.map((g,i)=>{const p={lat:g.reduce((s,m)=>s+Number(m.latest.lat),0)/g.length,lng:g.reduce((s,m)=>s+Number(m.latest.lng),0)/g.length},q=pos(p);if(g.length>1)return '<button type="button" class="loc-cluster" style="left:'+q.x+'px;top:'+q.y+'px" aria-label="'+g.length+' anggota di area ini" onclick="locCluster('+i+')">'+g.length+'</button>';const m=g[0];return '<button type="button" class="loc-pin '+locStatus(m.latest)+' '+(m.id===locDetail?'chosen':'')+'" style="left:'+q.x+'px;top:'+q.y+'px" onclick="'+locHandler('locMarker',m.id)+'" aria-label="'+E('Lokasi '+m.name)+'"><span>'+E(locInitials(m.name))+'</span></button>'}).join('');
const m=locMembers().find(m=>m.id===locDetail);if(locPopup&&m&&locAge(m.latest)!==null)markers+='<div class="loc-map-popup" style="left:'+Math.max(Math.min(145,w/2),Math.min(w-Math.min(145,w/2),pos(m.latest).x))+'px;top:'+Math.max(250,Math.min(h-20,pos(m.latest).y-25))+'px"><button type="button" class="loc-popup-close" aria-label="Tutup informasi anggota" onclick="locPopup=false;drawFieldMap()">×</button><span class="loc-avatar">'+E(locInitials(m.name))+'</span><strong>'+E(m.name)+'</strong><span>'+E(m.role)+'</span><small>'+E(locAgo(m.latest))+' · '+E(fieldTime(m.latest.captured))+' WITA</small><span>'+E(locCoordinates(m.latest))+'</span></div>';
if(locClusterIds.length)markers+='<div class="loc-cluster-popup"><button type="button" onclick="locClusterIds=[];drawFieldMap()">Tutup</button><strong>Anggota di area ini</strong>'+locMembers().filter(m=>locClusterIds.includes(m.id)).map(m=>'<button type="button" onclick="'+locHandler('locOpen',m.id)+'">'+E(m.name)+'</button>').join('')+'</div>';
const cursor=mapState.replay>=0?points[mapState.replay]:points.find(p=>p.id===mapState.selectedPoint);if(cursor){const q=pos(cursor);markers+='<span class="journeycursor" style="left:'+q.x+'px;top:'+q.y+'px">●<small>'+E(fieldTime(cursor.captured))+'</small></span>'}layers.innerHTML=tiles+route+markers+(!groups.length&&!points.length?'<div class="mapemptystate">'+(fieldLoading?'Memuat lokasi…':'Belum ada titik GPS untuk tampilan ini')+'</div>':'');
map.onpointerdown=e=>{if(e.target.closest('button,a,.loc-map-banner,.loc-map-popup,.loc-cluster-popup'))return;fieldMapDrag={x:e.clientX,y:e.clientY,center:projectMap(mapState.lat,mapState.lng,z)};map.setPointerCapture?.(e.pointerId)};map.onpointermove=e=>{if(!fieldMapDrag)return;Object.assign(mapState,unprojectMap(fieldMapDrag.center.x-(e.clientX-fieldMapDrag.x),fieldMapDrag.center.y-(e.clientY-fieldMapDrag.y),z));mapState.fitted=true;drawFieldMap()};map.onpointerup=map.onpointercancel=()=>{fieldMapDrag=null};const label=document.querySelector('#replayTime');if(label)label.textContent=cursor?fieldTime(cursor.captured):'';
};
const locAttendanceJourney=openAttendanceJourney;
openAttendanceJourney=function(member,day){locDetail=member;locJourney=true;locPopup=false;locAttendanceJourney(member,day)};
const locLogout=logoutLocal;logoutLocal=function(){locDetail='';locQuery='';locBucket='';locJourney=false;locPopup=false;locClusterIds=[];locDataScope='';locLogout()};
const locGo=go;go=function(page,id=''){if(page==='Lokasi Tim'&&view!=='Lokasi Tim'&&!locJourney){locDetail='';locQuery='';locBucket='';mapState.fitted=false}locGo(page,id)};

function locRequestMember(){if(authUser?.role==='AO')return authUser.id;const scoped=locDataScope===locScope()?fieldData?.members||[]:[];return scoped.some(m=>m.id===fieldMember)?fieldMember:''}
const locLoadField=loadField;loadField=async function(force=false){const scope=locScope(),before=fieldData;fieldMember=locRequestMember();await locLoadField(force);if(scope===locScope()&&fieldData!==before&&!fieldError){locDataScope=scope;if(view==='Lokasi Tim')renderContent()}};
const locRenderContent=renderContent;renderContent=function(){const input=view==='Lokasi Tim'&&document.activeElement?.matches?.('.loc-search input')?document.activeElement:null,selection=input?[input.selectionStart,input.selectionEnd]:null;locRenderContent();if(input){const next=document.querySelector('.loc-search input');next?.focus({preventScroll:true});try{next?.setSelectionRange(...selection)}catch{}}};
if(typeof window!=='undefined')window.addEventListener('resize',()=>{if(view==='Lokasi Tim'){mapState.fitted=false;drawFieldMap()}});
